import 'package:flutter/material.dart';
import 'dashboard.dart';import 'plan_page.dart';import 'subjects_page.dart';import 'ai_page.dart';import 'profile_page.dart';
class HomeShell extends StatefulWidget{const HomeShell({super.key});@override State<HomeShell> createState()=>_HomeShellState();}
class _HomeShellState extends State<HomeShell>{int index=0;final pages=const[Dashboard(),PlanPage(),SubjectsPage(),AiPage(),ProfilePage()];final labels=['الرئيسية','الخطة','المواد','AI','حسابي'];final icons=[Icons.home_rounded,Icons.calendar_month_rounded,Icons.menu_book_rounded,Icons.auto_awesome_rounded,Icons.person_rounded];@override Widget build(BuildContext c)=>Directionality(textDirection:TextDirection.rtl,child:Scaffold(body:SafeArea(child:IndexedStack(index:index,children:pages)),bottomNavigationBar:NavigationBar(selectedIndex:index,onDestinationSelected:(v)=>setState(()=>index=v),destinations:[for(var i=0;i<labels.length;i++)NavigationDestination(icon:Icon(icons[i]),label:labels[i])]));}
}
